<template><div><PageHeader title="薪酬管理" description="维护薪酬档案，执行月度试算和工资条发布"><el-date-picker v-model="month" type="month" value-format="YYYY-MM"/><el-button @click="openConfig">薪酬配置</el-button><el-button type="primary" :loading="calculating" @click="calculate">月度试算</el-button><el-button type="success" :loading="publishing" @click="publish">确认发布</el-button></PageHeader><section class="panel"><el-table v-loading="loading" :data="records"><el-table-column prop="employee_id" label="员工 ID"/><el-table-column prop="base_salary" label="基本工资"/><el-table-column prop="allowance" label="津贴"/><el-table-column prop="attendance_deduct" label="出勤扣款"/><el-table-column prop="social_security" label="社保"/><el-table-column prop="housing_fund" label="公积金"/><el-table-column prop="tax" label="个税"/><el-table-column prop="gross_salary" label="应发"/><el-table-column prop="net_salary" label="实发"/><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':'warning'">{{row.status==='PUBLISHED'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='PUBLISHED'" link @click="openAdjustment(row)">补发修正</el-button></template></el-table-column></el-table></section><el-dialog v-model="configVisible" title="新增薪酬配置" width="620"><el-form :model="config" label-position="top" class="form-grid"><el-form-item label="员工 ID"><el-input-number v-model="config.employee_id" :min="1"/></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="config.effective_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="基本工资"><el-input-number v-model="config.base_salary" :min="0" :precision="2"/></el-form-item><el-form-item label="岗位津贴"><el-input-number v-model="config.allowance" :min="0" :precision="2"/></el-form-item><el-form-item label="社保个人部分"><el-input-number v-model="config.social_security" :min="0" :precision="2"/></el-form-item><el-form-item label="公积金个人部分"><el-input-number v-model="config.housing_fund" :min="0" :precision="2"/></el-form-item><el-form-item label="个税起征点"><el-input-number v-model="config.tax_threshold" :min="0" :precision="2"/></el-form-item></el-form><template #footer><el-button @click="configVisible=false">取消</el-button><el-button type="primary" @click="saveConfig">保存</el-button></template></el-dialog><el-dialog v-model="adjustVisible" title="补发 / 修正记录" width="440"><el-form label-position="top"><el-form-item label="调整金额"><el-input-number v-model="adjust.amount" :precision="2"/></el-form-item><el-form-item label="原因"><el-input v-model="adjust.reason" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="adjustVisible=false">取消</el-button><el-button type="primary" @click="saveAdjustment">保存</el-button></template></el-dialog></div></template>
<script setup>
import{onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import PageHeader from'../components/PageHeader.vue';import{salaryApi}from'../api';const month=ref(new Date().toISOString().slice(0,7)),records=ref([]),loading=ref(false),calculating=ref(false),publishing=ref(false),configVisible=ref(false),adjustVisible=ref(false);const config=reactive({employee_id:null,base_salary:0,allowance:0,social_security:0,housing_fund:0,tax_threshold:5000,effective_date:new Date().toISOString().slice(0,10)}),adjust=reactive({salary_record_id:null,amount:0,reason:''});async function load(){loading.value=true;try{records.value=(await salaryApi.records({month:month.value})).data||[]}catch(e){ElMessage.error(e.businessMessage)}finally{loading.value=false}}async function calculate(){calculating.value=true;try{records.value=(await salaryApi.calculate({month:month.value})).data||[];ElMessage.success('试算完成')}catch(e){ElMessage.error(e.businessMessage)}finally{calculating.value=false}}async function publish(){try{await ElMessageBox.confirm(`确认发布 ${month.value} 工资条？发布后不可修改。`,'发布工资条',{type:'warning'});publishing.value=true;await salaryApi.publish({month:month.value});ElMessage.success('发布成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.businessMessage)}finally{publishing.value=false}}function openConfig(){configVisible.value=true}async function saveConfig(){try{const data={...config};for(const k of['base_salary','allowance','social_security','housing_fund','tax_threshold'])data[k]=String(data[k]);await salaryApi.saveConfig(data);ElMessage.success('薪酬配置已保存');configVisible.value=false}catch(e){ElMessage.error(e.businessMessage)}}function openAdjustment(row){Object.assign(adjust,{salary_record_id:row.id,amount:0,reason:''});adjustVisible.value=true}async function saveAdjustment(){if(!adjust.reason)return ElMessage.warning('请输入原因');try{await salaryApi.adjustment({...adjust,amount:String(adjust.amount)});ElMessage.success('补发记录已创建');adjustVisible.value=false}catch(e){ElMessage.error(e.businessMessage)}}watch(month,load);onMounted(load)
</script>
